def shortest_peak_stretch(badges):
    count = {}
    first = {}
    best_count, best_len = 0, 0
    for i, b in enumerate(badges):
        if b not in first:
            first[b] = i
        count[b] = count.get(b, 0) + 1
        span = i - first[b] + 1
        if count[b] > best_count or (count[b] == best_count and span < best_len):
            best_count, best_len = count[b], span
    return best_len

