def shortest_peak_stretch(badges):
    if not badges:
        return 0
    count, first, last = {}, {}, {}
    for i, b in enumerate(badges):
        count[b] = count.get(b, 0) + 1
        first.setdefault(b, i)
        last[b] = i
    top = max(count, key=count.get)
    return last[top] - first[top] + 1

def shortest_peak_stretch(badges):
    count, first, last = {}, {}, {}
    for i, b in enumerate(badges):
        count[b] = count.get(b, 0) + 1
        first.setdefault(b, i)
        last[b] = i
    peak = max(count.values(), default=0)
    return min((last[b] - first[b] for b in count if count[b] == peak), default=0)

def shortest_peak_stretch(badges):
    n = len(badges)
    total = {}
    for b in badges:
        total[b] = total.get(b, 0) + 1
    peak = max(total.values(), default=0)
    best = n
    for i in range(n):
        seen = {}
        top = 0
        for j in range(i, n):
            seen[badges[j]] = seen.get(badges[j], 0) + 1
            top = max(top, seen[badges[j]])
            if top == peak:
                best = min(best, j - i + 1)
                break
    return best
